final class PackageRenderingTest {
    private static final BlockPos PLACE=new BlockPos(1316,3,9);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var hidden=new AtomicBoolean();context.runOnClient(client->{hidden.set(client.gui.hud.isHidden());if(hidden.get())client.gui.hud.toggle();});
        server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1316 7 12");context.waitFor(client->Math.abs(client.player.getX()-1316.5)<.1,300);
        var ready=new AtomicBoolean();for(int i=0;i<300&&!ready.get();i++){server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();ready.set(level.hasChunkAt(new BlockPos(1296,3,0))&&level.hasChunkAt(new BlockPos(1327,3,15)));});if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError("Package scene server chunks missing");
        server.runCommand("fill 1296 3 0 1327 3 15 minecraft:smooth_quartz");server.runCommand("tp @p 1316 4 12");context.waitFor(client->client.level.getBlockState(PLACE).is(Blocks.SMOOTH_QUARTZ)&&Math.abs(client.player.getX()-1316.5)<.1,300);world.getConnection().waitForChunksRender();
        server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.setHealth(player.getMaxHealth());player.resetFallDistance();});server.runCommand("gamemode survival @p");server.runCommand("item replace entity @p weapon.mainhand with create:package_filter");context.waitFor(client->!client.player.isSpectator()&&client.player.getMainHandItem().is(AllItems.PACKAGE_FILTER),200);
        context.getInput().lookAt(new BlockPos(1316,20,5));context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.gui.screen() instanceof PackageFilterScreen,200);context.getInput().pressKey(options->options.keyInventory);context.runOnClient(client->{if(!(client.gui.screen() instanceof PackageFilterScreen))throw new AssertionError("Inventory letter closed focused address input");});context.getInput().typeChars("Oil *");context.waitFor(client->client.gui.screen() instanceof PackageFilterScreen screen&&screen.address().equals("Oil *"),200);context.waitTicks(3);context.takeScreenshot("create-vulkan-package-address-filter");context.clickScreenButton("✓");
        context.waitFor(client->client.gui.screen()==null&&PackageItem.getAddress(client.player.getMainHandItem()).equals("Oil *"),200);
        context.waitTicks(5);
        context.getInput().pressKey(options->options.keyUse);
        context.waitFor(client->client.gui.screen() instanceof PackageFilterScreen screen&&screen.address().equals("Oil *"),200);
        context.clickScreenButton("×");
        context.waitFor(client->client.gui.screen() instanceof PackageFilterScreen screen&&screen.address().isEmpty(),200);
        context.clickScreenButton("✓");
        context.waitFor(client->client.gui.screen()==null&&!client.player.getMainHandItem().has(AllDataComponents.PACKAGE_ADDRESS),200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var player=level.getServer().getPlayerList().getPlayers().getFirst();var box=PackageItem.containing(List.of(new ItemStack(Items.APPLE,12)));PackageItem.addAddress(box,"Placed");player.setItemInHand(InteractionHand.MAIN_HAND,box);player.inventoryMenu.broadcastChanges();});context.waitFor(client->PackageItem.isPackage(client.player.getMainHandItem()),200);
        lookAt(context,Vec3.atCenterOf(PLACE).add(0,.5,0));
        context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(PLACE),200);context.getInput().pressKey(options->options.keyUse);
        context.waitFor(client->client.player.getMainHandItem().isEmpty()&&client.level.getEntitiesOfClass(PackageEntity.class,new AABB(PLACE).inflate(2)).stream().anyMatch(box->box.getAddress()!=null&&box.getAddress().equals("Placed")),200);
        var placed=context.computeOnClient(client->client.level.getEntitiesOfClass(PackageEntity.class,new AABB(PLACE).inflate(2)).getFirst().getUUID());
        context.runOnClient(client->{var entity=client.level.getEntitiesOfClass(PackageEntity.class,new AABB(PLACE).inflate(2)).getFirst();assertMaterials(client,entity);var rendered=client.getEntityRenderDispatcher().extractEntity(entity,.5f);if(!(rendered instanceof PackageRenderer.State state)||state.model.isEmpty()||state.model.mesh==null||state.model.mesh.size()==0)throw new AssertionError("Native package entity mesh missing");if(PackageItem.getContents(entity.getBox()).getFirst().getCount()!=12)throw new AssertionError("Spawn data lost package contents");});
        lookAt(context,context.computeOnClient(client->{var entity=client.level.getEntitiesOfClass(PackageEntity.class,new AABB(PLACE).inflate(2)).getFirst();return entity.position().add(0,entity.getBbHeight()/2,0);}));context.waitFor(client->client.hitResult instanceof EntityHitResult hit&&hit.getEntity().getUUID().equals(placed),200);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->PackageItem.isPackage(client.player.getMainHandItem())&&PackageItem.getAddress(client.player.getMainHandItem()).equals("Placed"),200);
        context.getInput().lookAt(new BlockPos(1316,20,5));context.waitTicks(5);context.getInput().holdShift();context.waitTicks(2);context.getInput().pressKey(options->options.keyUse);context.getInput().releaseShift();context.waitFor(client->{int apples=0;for(int slot=0;slot<36;slot++)if(client.player.getInventory().getItem(slot).is(Items.APPLE))apples+=client.player.getInventory().getItem(slot).getCount();return !PackageItem.isPackage(client.player.getMainHandItem())&&apples==12;},200);server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();int apples=0;for(int i=0;i<36;i++)if(player.getInventory().getItem(i).is(Items.APPLE))apples+=player.getInventory().getItem(i).getCount();if(apples!=12)throw new AssertionError("Native sneak-open duplicated or lost contents: "+apples);});
        server.runCommand("gamemode spectator @p");server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();for(int i=0;i<PackageStyles.ALL_BOXES.size();i++){var stack=new ItemStack(PackageStyles.ALL_BOXES.get(i));var box=PackageEntity.fromItemStack(level,new Vec3(1298.5+(i%7)*2,4,3.5+(i/7)*3),stack);box.setYRot(0);level.addFreshEntity(box);}});
        logistics(context,world);
        server.runCommand("tp @p 1305 10 14");context.waitFor(client->Math.abs(client.player.getX()-1305.5)<.1&&client.level.getEntitiesOfClass(PackageEntity.class,new AABB(1296,3,0,1327,8,15)).size()==14,300);context.getInput().lookAt(new BlockPos(1305,4,5));world.getConnection().waitForChunksRender();context.runOnClient(client->{for(var entity:client.level.getEntitiesOfClass(PackageEntity.class,new AABB(1296,3,0,1327,8,15))){assertMaterials(client,entity);var rendered=client.getEntityRenderDispatcher().extractEntity(entity,.5f);if(!(rendered instanceof PackageRenderer.State state)||state.model.isEmpty()||state.model.mesh==null||state.model.mesh.size()==0)throw new AssertionError("Style model did not extract: "+entity.getBox());}});context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot("create-vulkan-package-styles");
        var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);context.runOnClient(client->{for(var entity:client.level.getEntitiesOfClass(PackageEntity.class,new AABB(1296,3,0,1327,8,15))){assertMaterials(client,entity);var state=(PackageRenderer.State)client.getEntityRenderDispatcher().extractEntity(entity,.5f);if(state.model.mesh==null||state.model.mesh.size()==0)throw new AssertionError("Package style failed after reload");}});
        server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();for(int i=0;i<120&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->unloaded.set(!world.getConnection().getServerLevel().isLoaded(new BlockPos(1305,4,5))));}if(!unloaded.get())throw new AssertionError("Package scene did not unload");server.runCommand("tp @p 1305 10 14");context.waitFor(client->Math.abs(client.player.getX()-1305.5)<.1&&client.level.getEntitiesOfClass(PackageEntity.class,new AABB(1296,3,0,1327,8,15)).size()==14,400);context.getInput().lookAt(new BlockPos(1305,4,5));world.getConnection().waitForChunksRender();context.takeScreenshot("create-vulkan-packages-after-chunk-return");throwPackage(context,world);context.runOnClient(client->{if(client.gui.hud.isHidden()!=hidden.get())client.gui.hud.toggle();});
    }
    private static void throwPackage(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();server.runCommand("tp @p 1320 4 12");context.waitFor(client->Math.abs(client.player.getX()-1320.5)<.1,200);
        server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.resetFallDistance();var box=PackageStyles.getDefaultBox();PackageItem.addAddress(box,"Thrown");player.setItemInHand(InteractionHand.MAIN_HAND,box);player.inventoryMenu.broadcastChanges();});server.runCommand("gamemode survival @p");context.waitFor(client->!client.player.isSpectator()&&PackageItem.getAddress(client.player.getMainHandItem()).equals("Thrown"),200);
        context.getInput().lookAt(new BlockPos(1320,15,-5));context.getInput().holdKeyFor(options->options.keyUse,25);
        var area=new AABB(1290,0,-30,1350,60,30);context.waitFor(client->client.player.getMainHandItem().isEmpty()&&client.level.getEntitiesOfClass(PackageEntity.class,area).stream().anyMatch(box->PackageItem.getAddress(box.getBox()).equals("Thrown")),200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var boxes=level.getEntitiesOfClass(PackageEntity.class,area,box->PackageItem.getAddress(box.getBox()).equals("Thrown"));if(boxes.size()!=1)throw new AssertionError("Real charged release duplicated package");boxes.getFirst().discard();});server.runCommand("gamemode spectator @p");
    }
    private static void logistics(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var depotPos=new BlockPos(1321,4,6);var chutePos=new BlockPos(1324,5,6);var beltPos=new BlockPos(1319,4,2);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(depotPos,AllBlocks.DEPOT.defaultBlockState());level.setBlockAndUpdate(chutePos.below(),Blocks.STONE.defaultBlockState());level.setBlockAndUpdate(chutePos,AllBlocks.CHUTE.defaultBlockState().setValue(com.simibubi.create.content.logistics.chute.ChuteBlock.SHAPE,com.simibubi.create.content.logistics.chute.ChuteBlock.Shape.WINDOW));var box=PackageStyles.getDefaultBox();box.set(AllDataComponents.PACKAGE_CONTENTS,net.minecraft.world.item.component.ItemContainerContents.fromItems(List.of(new ItemStack(Items.APPLE,8))));var depot=(com.simibubi.create.content.logistics.depot.DepotBlockEntity)level.getBlockEntity(depotPos);try(var tx=net.fabricmc.fabric.api.transfer.v1.transaction.Transaction.openOuter()){depot.inventory.inputs.getFirst().insert(net.fabricmc.fabric.api.transfer.v1.item.ItemVariant.of(box),1,tx);tx.commit();}((com.simibubi.create.content.logistics.chute.ChuteBlockEntity)level.getBlockEntity(chutePos)).setItem(box,.5f);var shaft=AllBlocks.SHAFT.defaultBlockState().setValue(com.simibubi.create.content.kinetics.simpleRelays.ShaftBlock.AXIS,Direction.Axis.Z);level.setBlockAndUpdate(beltPos,shaft);level.setBlockAndUpdate(beltPos.east(5),shaft);if(!com.simibubi.create.content.kinetics.belt.item.BeltConnectorItem.createBelts(level,beltPos,beltPos.east(5)))throw new AssertionError("Package client belt missing");var belt=(com.simibubi.create.content.kinetics.belt.BeltBlockEntity)level.getBlockEntity(beltPos.east(2));try(var tx=net.fabricmc.fabric.api.transfer.v1.transaction.Transaction.openOuter()){if(belt.storage(Direction.UP).insert(net.fabricmc.fabric.api.transfer.v1.item.ItemVariant.of(box),1,tx)!=1)throw new AssertionError("Package belt cargo rejected");tx.commit();}});
        server.runCommand("tp @p 1322 8 12");context.waitFor(client->client.level.getBlockEntity(chutePos) instanceof com.simibubi.create.content.logistics.chute.ChuteBlockEntity chute&&PackageItem.isPackage(chute.getItem())&&client.level.getBlockEntity(beltPos.east(2)) instanceof com.simibubi.create.content.kinetics.belt.BeltBlockEntity belt&&belt.getControllerBE()!=null&&!belt.getControllerBE().getInventory().getTransportedItems().isEmpty(),300);context.getInput().lookAt(new BlockPos(1322,4,5));world.getConnection().waitForChunksRender();context.runOnClient(client->{var chute=client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(chutePos),.5f,null,true);if(!(chute instanceof com.simibubi.create.content.logistics.chute.ChuteRenderer.State state)||!state.packageItem||state.item.isEmpty())throw new AssertionError("Chute did not extract package scale and model");var belt=client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(beltPos.east(2)),.5f,null,false);if(!(belt instanceof com.simibubi.create.content.kinetics.belt.BeltRenderer.State beltState)||beltState.items.size()!=1||!beltState.items.getFirst().packageItem())throw new AssertionError("Belt did not extract package scale and model");});context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot("create-vulkan-packages-depot-belt-chute");
    }
    private static void assertMaterials(net.minecraft.client.Minecraft client,PackageEntity entity){
        var model=client.getModelManager().getModel(PackageRenderer.model(entity.getBox()));
        var parts=new ArrayList<net.minecraft.client.renderer.block.dispatch.BlockStateModelPart>();model.collectParts(net.minecraft.util.RandomSource.create(42),parts);
        for(var part:parts){var quads=new ArrayList<net.minecraft.client.resources.model.geometry.BakedQuad>(part.getQuads(null));for(var side:Direction.values())quads.addAll(part.getQuads(side));for(var quad:quads)if(!quad.materialInfo().sprite().contents().name().getPath().contains("package/"))throw new AssertionError("Package material missing: "+entity.getBox()+" -> "+quad.materialInfo().sprite().contents().name());}
    }
    private static void lookAt(ClientGameTestContext context,Vec3 point){var rotation=context.computeOnClient(client->{var delta=point.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(rotation.x,rotation.y);}
}
